#!/usr/bin/env node
/**
 * Generate IDE-specific adapters from the `.agents/` source of truth.
 *
 *   node .agents/scripts/sync_targets.mjs --target claude,cursor [--root <dir>]
 *   node .agents/scripts/sync_targets.mjs --target all
 *   node .agents/scripts/sync_targets.mjs            # re-sync the targets chosen earlier
 *
 * Targets and what they generate (never edit generated files — edit .agents/ and re-run):
 *   antigravity  nothing extra: `.agents/` (rules, skills, workflows, hooks.json, mcp_config.json) is native
 *   claude       CLAUDE.md, .claude/{agents,skills,commands,settings.json}, .mcp.json
 *   cursor       .cursor/rules/*.mdc, .cursor/commands/*.md, .cursor/mcp.json
 *   codex        AGENTS.md
 *   vscode       .github/{copilot-instructions.md,prompts,agents}, .vscode/mcp.json
 *
 * Files are only overwritten when they did not exist or were generated by a previous run.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const TARGETS = {
  antigravity: 'Google Antigravity / Gemini CLI',
  claude: 'Claude Code',
  cursor: 'Cursor',
  codex: 'Codex',
  vscode: 'VS Code (GitHub Copilot)'
};

const STATE_FILE = '.agents/.agent-kit/generated.json';
const MARK = 'Generated by Agent Kit';
const CLAUDE_TOOLS = new Set(['Read', 'Write', 'Edit', 'Bash', 'Grep', 'Glob', 'Agent', 'WebFetch', 'WebSearch', 'NotebookEdit']);

const csv = v => (v || '').split(',').map(s => s.trim()).filter(Boolean);
const yamlStr = v => JSON.stringify(v.replace(/^["']|["']$/g, ''));
const clip = (v, n) => { const s = v.replace(/^["']|["']$/g, ''); return s.length > n ? `${s.slice(0, n - 1)}…` : s; };

function splitFrontmatter(text) {
  const m = text.replace(/\r\n/g, '\n').match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if (!m) return { fm: {}, body: text };
  const fm = {};
  for (const line of m[1].split('\n')) {
    const kv = line.match(/^([A-Za-z_-]+):\s*(.*)$/);
    if (kv) fm[kv[1]] = kv[2].trim();
  }
  return { fm, body: m[2] };
}

export function parseTargets(value) {
  const names = csv(value);
  const list = names.includes('all') ? Object.keys(TARGETS) : names;
  const bad = list.filter(t => !TARGETS[t]);
  if (bad.length) throw new Error(`Unknown target(s): ${bad.join(', ')}. Valid: ${Object.keys(TARGETS).join(', ')}, all`);
  return [...new Set(list)];
}

export function sync(root, targets) {
  const src = path.join(root, '.agents');
  const statePath = path.join(root, STATE_FILE);
  const prev = fs.existsSync(statePath) ? JSON.parse(fs.readFileSync(statePath, 'utf8')) : { targets: [], files: {} };
  const owned = new Set(Object.values(prev.files).flat());
  const written = {};
  let current;
  const skipped = [];

  const emit = (rel, content) => {
    const abs = path.join(root, rel);
    if (fs.existsSync(abs) && !owned.has(rel)) { skipped.push(rel); return; }
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, content);
    written[current].add(rel);
  };
  const mergeJson = (rel, mutate) => {
    const abs = path.join(root, rel);
    let data = {};
    if (fs.existsSync(abs)) {
      try { data = JSON.parse(fs.readFileSync(abs, 'utf8')); } catch { skipped.push(rel); return; }
    }
    mutate(data);
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, `${JSON.stringify(data, null, 2)}\n`);
  };
  const copyTree = (from, toRel) => {
    for (const e of fs.readdirSync(from, { withFileTypes: true })) {
      if (e.name === '__pycache__') continue;
      if (e.isDirectory()) copyTree(path.join(from, e.name), `${toRel}/${e.name}`);
      else emit(`${toRel}/${e.name}`, fs.readFileSync(path.join(from, e.name)));
    }
  };

  // ── read the source of truth ──────────────────────────────────────────────
  const list = dir => (fs.existsSync(dir) ? fs.readdirSync(dir).filter(f => f.endsWith('.md')).sort() : []);
  const read = file => splitFrontmatter(fs.readFileSync(file, 'utf8'));

  const rules = list(path.join(src, 'rules')).map(f => ({ f, ...read(path.join(src, 'rules', f)) }));
  const alwaysRules = rules.filter(r => r.fm.trigger === 'always_on');
  const demandRules = rules.filter(r => r.fm.trigger !== 'always_on');
  const agents = list(path.join(src, 'agent')).map(f => ({ f, ...read(path.join(src, 'agent', f)) }));
  const workflows = list(path.join(src, 'workflows')).map(f => ({ f, ...read(path.join(src, 'workflows', f)) }));
  const skillsDir = path.join(src, 'skills');
  const skills = fs.readdirSync(skillsDir, { withFileTypes: true })
    .filter(e => e.isDirectory() && fs.existsSync(path.join(skillsDir, e.name, 'SKILL.md')))
    .map(e => ({ name: e.name, ...read(path.join(skillsDir, e.name, 'SKILL.md')) }));
  const skillNames = new Set(skills.map(s => s.name));
  const mcpPath = path.join(src, 'mcp_config.json');
  const mcpServers = fs.existsSync(mcpPath) ? JSON.parse(fs.readFileSync(mcpPath, 'utf8')).mcpServers || {} : {};
  const addServers = key => data => { data[key] = { ...mcpServers, ...(data[key] || {}) }; };

  const htmlMark = `<!-- ${MARK} from .agents/ — edit the source, then run \`npm run sync:targets\`. -->`;
  const agentCatalog = prefix => agents.map(a => `- \`${a.fm.name || a.f.replace(/\.md$/, '')}\` (${prefix}agent/${a.f}) — ${clip(a.fm.description || '', 110)}`).join('\n');
  const skillCatalog = prefix => skills.map(s => `- \`${s.name}\` (${prefix}skills/${s.name}/SKILL.md) — ${clip(s.fm.description || '', 110)}`).join('\n');
  const workflowCatalog = prefix => workflows.map(w => `- \`/${w.f.replace(/\.md$/, '')}\` (${prefix}workflows/${w.f}) — ${clip(w.fm.description || '', 110)}`).join('\n');

  // Plain-markdown adapter used by tools that cannot import files (Codex, Copilot).
  const pointerDoc = (title, prefix, link) => [
    htmlMark,
    `# ${title}`,
    '',
    'Agent Kit keeps all rules, agents, skills and workflows in `.agents/` (single source of truth).',
    '',
    '## Read first, every session',
    ...alwaysRules.map(r => `- ${link(`rules/${r.f}`)}`),
    `- ${link('memory/MEMORY.md')}`,
    '',
    '## Read when relevant',
    ...demandRules.map(r => `- ${link(`rules/${r.f}`)}${r.fm.description ? ` — ${r.fm.description}` : ''}`),
    '',
    '## Slash workflows',
    'When the user types `/name`, open the matching workflow file and follow it.',
    workflowCatalog(prefix),
    '',
    '## Specialist agents',
    'Adopt the persona of the best-matching agent file and load the skills in its `skills:` frontmatter.',
    agentCatalog(prefix),
    '',
    '## Skills',
    'Read `SKILL.md` first, then only the sections you need.',
    skillCatalog(prefix),
    ''
  ].join('\n');

  const builders = {
    antigravity() {},

    claude() {
      for (const s of skills) copyTree(path.join(skillsDir, s.name), `.claude/skills/${s.name}`);
      for (const a of agents) {
        const tools = csv(a.fm.tools).filter(t => CLAUDE_TOOLS.has(t));
        const sk = csv(a.fm.skills).filter(n => skillNames.has(n));
        const head = ['---', `name: ${a.fm.name || a.f.replace(/\.md$/, '')}`, `description: ${yamlStr(a.fm.description || '')}`];
        if (tools.length) head.push(`tools: ${tools.join(', ')}`);
        if (a.fm.model) head.push(`model: ${a.fm.model}`);
        if (sk.length) head.push('skills:', ...sk.map(n => `  - ${n}`));
        emit(`.claude/agents/${a.f}`, [...head, '---', htmlMark, '', a.body.trimStart()].join('\n'));
      }
      for (const w of workflows) {
        emit(`.claude/commands/${w.f}`, ['---', `description: ${yamlStr(w.fm.description || w.f)}`, 'argument-hint: "[request]"', '---', htmlMark, '', w.body.trimStart(), '', 'User request: $ARGUMENTS', ''].join('\n'));
      }
      mergeJson('.claude/settings.json', data => {
        const hook = { type: 'command', command: 'node "$CLAUDE_PROJECT_DIR/.agents/hooks/validate-tool-call.mjs"', timeout: 10 };
        data.hooks ??= {};
        data.hooks.PreToolUse ??= [];
        const present = data.hooks.PreToolUse.some(e => (e.hooks || []).some(h => (h.command || '').includes('validate-tool-call')));
        if (!present) data.hooks.PreToolUse.push({ matcher: 'Bash', hooks: [hook] });
      });
      mergeJson('.mcp.json', addServers('mcpServers'));
      emit('CLAUDE.md', [
        htmlMark,
        '# Agent Kit (Claude Code)',
        '',
        '`.agents/` is the source of truth; `.claude/` is generated from it.',
        'Subagents: `.claude/agents/`. Skills: `.claude/skills/`. Slash commands: `.claude/commands/`.',
        'Where rules say `.agents/skills/...`, the same skill is also installed as a native skill under `.claude/skills/`.',
        '',
        '## Always-on rules',
        ...alwaysRules.map(r => `@.agents/rules/${r.f}`),
        '',
        '## Memory',
        '@.agents/memory/MEMORY.md',
        '',
        '## Read on demand',
        ...demandRules.map(r => `- \`.agents/rules/${r.f}\`${r.fm.description ? ` — ${r.fm.description}` : ''}`),
        ''
      ].join('\n'));
    },

    cursor() {
      const link = rel => `[${rel}](mdc:.agents/${rel})`;
      emit('.cursor/rules/agent-kit.mdc', [
        '---', 'description: Agent Kit core protocol, routing and universal rules', 'alwaysApply: true', '---', htmlMark,
        '# Agent Kit', '',
        'All rules, agents, skills and workflows live in `.agents/`. Read these files before doing any work:',
        ...alwaysRules.map(r => `- ${link(`rules/${r.f}`)}`),
        `- ${link('memory/MEMORY.md')}`,
        '', 'Read when relevant:',
        ...demandRules.map(r => `- ${link(`rules/${r.f}`)}${r.fm.description ? ` — ${r.fm.description}` : ''}`), ''
      ].join('\n'));
      emit('.cursor/rules/agent-kit-catalog.mdc', [
        '---', 'description: Catalog of Agent Kit specialist agents, skills and workflows. Use to pick the right agent or skill for a task.', 'alwaysApply: false', '---', htmlMark,
        '## Specialist agents', 'Adopt the best-matching persona and load its skills.', agentCatalog('.agents/'),
        '', '## Skills', skillCatalog('.agents/'), ''
      ].join('\n'));
      for (const w of workflows) emit(`.cursor/commands/${w.f}`, `${htmlMark}\n\n${w.body.trimStart()}`);
      mergeJson('.cursor/mcp.json', addServers('mcpServers'));
    },

    codex() {
      emit('AGENTS.md', pointerDoc('Agent Kit', '.agents/', rel => `\`.agents/${rel}\``));
    },

    vscode() {
      emit('.github/copilot-instructions.md', pointerDoc('Agent Kit', '.agents/', rel => `[.agents/${rel}](../.agents/${rel})`));
      for (const w of workflows) {
        const name = w.f.replace(/\.md$/, '');
        emit(`.github/prompts/${name}.prompt.md`, ['---', `description: ${yamlStr(w.fm.description || name)}`, 'agent: agent', '---', htmlMark, '', w.body.trimStart(), ''].join('\n'));
      }
      for (const a of agents) {
        const name = a.fm.name || a.f.replace(/\.md$/, '');
        emit(`.github/agents/${name}.agent.md`, ['---', `name: ${name}`, `description: ${yamlStr(a.fm.description || '')}`, '---', htmlMark, '', a.body.trimStart()].join('\n'));
      }
      mergeJson('.vscode/mcp.json', addServers('servers'));
    }
  };

  for (const t of targets) {
    current = t;
    written[t] = new Set();
    builders[t]();
    // Remove files this target generated earlier that are no longer produced.
    for (const rel of prev.files[t] || []) {
      if (!written[t].has(rel) && fs.existsSync(path.join(root, rel))) fs.rmSync(path.join(root, rel));
    }
  }
  const files = { ...prev.files };
  for (const t of targets) files[t] = [...written[t]].sort();
  const kept = [...new Set([...prev.targets, ...targets])];
  fs.mkdirSync(path.dirname(statePath), { recursive: true });
  fs.writeFileSync(statePath, `${JSON.stringify({ targets: kept, files }, null, 2)}\n`);
  return { targets, files: targets.reduce((n, t) => n + written[t].size, 0), skipped };
}

function main() {
  const arg = name => { const i = process.argv.indexOf(name); return i > -1 ? process.argv[i + 1] : undefined; };
  const root = path.resolve(arg('--root') ?? path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..'));
  const statePath = path.join(root, STATE_FILE);
  let targets;
  try {
    const chosen = arg('--target');
    targets = chosen !== undefined ? parseTargets(chosen) : (fs.existsSync(statePath) ? JSON.parse(fs.readFileSync(statePath, 'utf8')).targets : []);
  } catch (e) {
    console.error(e.message);
    process.exit(1);
  }
  if (!targets.length) {
    console.error(`Usage: sync_targets.mjs --target <${Object.keys(TARGETS).join('|')}|all>[,...] [--root <dir>]`);
    process.exit(1);
  }
  const res = sync(root, targets);
  console.log(`Agent Kit: synced ${targets.join(', ')} (${res.files} files).`);
  for (const s of res.skipped) console.warn(`  skipped ${s} — exists and was not generated by Agent Kit`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
